using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using ConventionMapper;
#if NET8_0_OR_GREATER
using System.Collections.Frozen;
using ConventionMapper.Tests.Proto;
using Google.Protobuf;
using Google.Protobuf.WellKnownTypes;
#endif

// End-to-end: immutable and frozen collections, and Protobuf messages generated by protoc, compiled by the generator and run.
namespace ConventionMapper.Tests.Integration
{
    public class Catalog
    {
        public List<string> Names { get; set; } = new List<string>();
        public int[] Codes { get; set; } = Array.Empty<int>();
        public Dictionary<string, int> Stock { get; set; } = new Dictionary<string, int>();
        public HashSet<string> Tags { get; set; } = new HashSet<string>();
    }

    public class CatalogSnapshot
    {
        public ImmutableArray<string> Names { get; set; }
        public ImmutableList<int> Codes { get; set; } = ImmutableList<int>.Empty;
        public ImmutableDictionary<string, int> Stock { get; set; } = ImmutableDictionary<string, int>.Empty;
        public ImmutableHashSet<string> Tags { get; set; } = ImmutableHashSet<string>.Empty;
    }

#if NET8_0_OR_GREATER
    public class CatalogLookup
    {
        public FrozenSet<string> Tags { get; set; } = FrozenSet<string>.Empty;
        public FrozenDictionary<string, int> Stock { get; set; } = FrozenDictionary<string, int>.Empty;
        public List<string> Names { get; set; } = new List<string>();
    }

    public enum OrderState { Unknown, Open, Shipped }
    public class LineDto { public string Sku { get; set; } = ""; public int Quantity { get; set; } }

    public class OrderDto
    {
        public int Id { get; set; }
        public string? Customer { get; set; }
        public DateTime PlacedAt { get; set; }
        public TimeSpan? Handling { get; set; }
        public string? Note { get; set; }
        public int? Priority { get; set; }
        public List<LineDto> Lines { get; set; } = new List<LineDto>();
        public List<string> Tags { get; set; } = new List<string>();
        public Dictionary<string, int> Counts { get; set; } = new Dictionary<string, int>();
        public byte[]? Signature { get; set; }
        public string? Email { get; set; }
        public string? Phone { get; set; }
    }
#endif

    [GeneratedMapper]
    public static partial class IntegrationMapper
    {
        public static partial CatalogSnapshot Snapshot(Catalog catalog);
        public static partial Catalog FromSnapshot(CatalogSnapshot snapshot);
#if NET8_0_OR_GREATER
        public static partial CatalogLookup Lookup(Catalog catalog);

        public static partial OrderMessage ToMessage(OrderDto order);
        public static partial OrderDto ToDto(OrderMessage message);
        public static partial LineMessage ToLine(LineDto line);
        public static partial LineDto ToLineDto(LineMessage line);
#endif
    }

    public class GeneratedIntegrationTests
    {
        private static Catalog Sample() => new Catalog
        {
            Names = new List<string> { "a", "b" }, Codes = new[] { 1, 2, 3 }, Stock = new Dictionary<string, int> { ["a"] = 5 }, Tags = new HashSet<string> { "x" },
        };

        [Fact]
        public void Immutable_collections_are_built_with_builders()
        {
            var snapshot = IntegrationMapper.Snapshot(Sample());
            Assert.Equal(new[] { "a", "b" }, snapshot.Names);
            Assert.Equal(new[] { 1, 2, 3 }, snapshot.Codes);
            Assert.Equal(5, snapshot.Stock["a"]);
            Assert.Contains("x", snapshot.Tags);

            var back = IntegrationMapper.FromSnapshot(snapshot);
            Assert.Equal(new[] { "a", "b" }, back.Names);
            Assert.Empty(IntegrationMapper.FromSnapshot(new CatalogSnapshot()).Names); // a default ImmutableArray reads as empty
            Assert.True(IntegrationMapper.Snapshot(new Catalog { Names = null! }).Names.IsEmpty);
        }

#if NET8_0_OR_GREATER
        [Fact]
        public void Frozen_collections_are_built()
        {
            var lookup = IntegrationMapper.Lookup(Sample());
            Assert.Contains("x", (IEnumerable<string>)lookup.Tags);
            Assert.Equal(5, lookup.Stock["a"]);
        }

        private static OrderDto Order() => new OrderDto
        {
            Id = 7, Customer = "Ann", PlacedAt = new DateTime(2024, 5, 1, 9, 30, 0, DateTimeKind.Utc), Handling = TimeSpan.FromMinutes(90),
            Note = null, Priority = 3, Lines = new List<LineDto> { new LineDto { Sku = "A", Quantity = 2 } }, Tags = new List<string> { "gift" },
            Counts = new Dictionary<string, int> { ["boxes"] = 2 }, Signature = new byte[] { 1, 2 }, Email = null, Phone = "555-0100",
        };

        [Fact]
        public void Dtos_map_to_protobuf_messages()
        {
            var message = IntegrationMapper.ToMessage(Order());

            Assert.Equal(7, message.Id);
            Assert.Equal(Timestamp.FromDateTime(new DateTime(2024, 5, 1, 9, 30, 0, DateTimeKind.Utc)), message.PlacedAt);
            Assert.Equal(Duration.FromTimeSpan(TimeSpan.FromMinutes(90)), message.Handling);
            Assert.Null(message.Note);                                 // wrapper: null stays null
            Assert.Equal(3, message.Priority);
            Assert.Equal("A", Assert.Single(message.Lines).Sku);        // repeated: added
            Assert.Equal(new[] { "gift" }, message.Tags);
            Assert.Equal(2, message.Counts["boxes"]);                   // map field
            Assert.Equal(new byte[] { 1, 2 }, message.Signature.ToByteArray());
            Assert.Equal(OrderMessage.ContactOneofCase.Phone, message.ContactCase); // a null Email didn't select the oneof
            Assert.Equal("555-0100", message.Phone);

            // A null string would make the protobuf setter throw; it is skipped instead.
            var noCustomer = Order();
            noCustomer.Customer = null;
            Assert.Equal("", IntegrationMapper.ToMessage(noCustomer).Customer);
        }

        [Fact]
        public void Protobuf_messages_map_back_to_dtos()
        {
            var dto = IntegrationMapper.ToDto(IntegrationMapper.ToMessage(Order()));

            Assert.Equal(new DateTime(2024, 5, 1, 9, 30, 0), dto.PlacedAt);
            Assert.Equal(TimeSpan.FromMinutes(90), dto.Handling);
            Assert.Equal("A", Assert.Single(dto.Lines).Sku);
            Assert.Equal(2, dto.Counts["boxes"]);
            Assert.Equal(new byte[] { 1, 2 }, dto.Signature);
            Assert.Equal("555-0100", dto.Phone);

            var empty = IntegrationMapper.ToDto(new OrderMessage());
            Assert.Equal(default, empty.PlacedAt);   // missing Timestamp
            Assert.Null(empty.Handling);
            Assert.Empty(empty.Lines);
        }
#endif
    }
}
